import type { ParsedGeo } from "./types";

export const ArmorBones = {
  HEAD: "armorHead",
  BODY: "armorBody",
  LEFT_ARM: "armorLeftArm",
  RIGHT_ARM: "armorRightArm",
  LEFT_ARM_SLIM: "armorLeftArmSlim",
  RIGHT_ARM_SLIM: "armorRightArmSlim",
  LEFT_LEG: "armorLeftLeg",
  RIGHT_LEG: "armorRightLeg",
  LEFT_BOOT: "armorLeftBoot",
  RIGHT_BOOT: "armorRightBoot",
} as const;

export const BipedBones = {
  RIG: "bipedRig",
  HEAD: "bipedHead",
  BODY: "bipedBody",
  LEFT_ARM: "bipedLeftArm",
  RIGHT_ARM: "bipedRightArm",
  LEFT_LEG: "bipedLeftLeg",
  RIGHT_LEG: "bipedRightLeg",
} as const;

export const ARMOR_BONE_NAMES = Object.values(ArmorBones);

const ARMOR_PREFIX = "armor";
const BIPED_PREFIX = "biped";

export function isArmorBone(name: string): boolean {
  return name.toLowerCase().startsWith(ARMOR_PREFIX);
}

export function isBipedBone(name: string): boolean {
  return name.toLowerCase().startsWith(BIPED_PREFIX);
}

export function hasArmorBones(geo: ParsedGeo): boolean {
  return geo.bones.some((b) => isArmorBone(b.name));
}
